{"cards": [{"node_code": "N_bdcbd964954e8535", "definition": "针对工程结构或岩土体发生的倾斜、裂缝及接缝变形进行观测、量测与分析的技术领域，旨在评估局部稳定性与结构完整性。", "boundary": "本节点聚焦于非整体位移类的局部几何变形监测。涵盖倾斜角、裂缝宽度/深度、接缝开合度等具体参数的测量方法、仪器选型及数据分析。与“沉降观测”的区别在于，本节点关注角度变化与线性开裂/分离，而非垂直高程变化；与“水平位移”的区别在于，本节点侧重结构内部或表面的局部破坏性变形，而非整体平动。", "includes": ["倾斜角、裂缝宽度与深度、接缝开合度的观测技术与仪器", "针对墙体、坝体、隧道衬砌等对象的局部变形监测方案", "局部变形数据的处理、趋势分析及适用条件评估"], "excludes": ["整体垂直沉降或高程变化监测（归入沉降观测）", "整体水平平动或挠度监测（归入水平位移与挠度观测）", "基于监测结果的结构承载力验算或安全鉴定（归入工程安全、检测与运维）"], "sibling_distinctions": [{"other_code": "N_7557e10122fd3104", "rule": "沉降观测侧重垂直方向的高程变化；本节点侧重倾斜角度及裂缝、接缝等局部线性变形。"}, {"other_code": "N_ec95fff4aeae6217", "rule": "水平位移与挠度侧重整体或构件的平动与弯曲变形；本节点侧重局部开裂、分离及倾斜等破坏性前兆变形。"}], "cross_boundary_rule": "若倾斜或裂缝监测数据用于整体结构安全预警，可关联自动化监测与预警节点，但具体的局部变形测量技术与方法主挂载本节点。"}, {"node_code": "N_b5df5bfc1ef97cd8", "definition": "针对基坑、边坡及地下工程在施工与运营期间的土体、支护结构及周围环境的变形进行监测的技术领域，旨在控制工程风险。", "boundary": "本节点聚焦于岩土工程环境下的变形监测。涵盖基坑支护结构（如桩、墙）的位移、边坡滑移、地下工程围岩收敛及地表沉降等。与“桥梁与高层结构”的区别在于，本节点对象主要为岩土体及其临时/永久支护结构，而非混凝土或钢结构主体；与“倾斜、裂缝”的区别在于，本节点更强调岩土体整体稳定性相关的位移场监测。", "includes": ["基坑支护结构位移、边坡滑移、地下工程围岩收敛监测", "基坑周边地表沉降、邻近建筑物及管线影响监测", "岩土工程变形监测方案、仪器布置及适用条件分析"], "excludes": ["桥梁、高层建筑等地上结构主体的变形监测（归入桥梁与高层结构变形监测）", "纯材料力学性能试验（归入通用试验）", "基于监测数据的边坡稳定性数值模拟或安全系数计算（归入岩土工程或安全评估）"], "sibling_distinctions": [{"other_code": "N_2ef38c16b3799f95", "rule": "桥梁与高层结构侧重地上刚性或柔性结构主体的变形；本节点侧重基坑、边坡等岩土工程环境及支护结构的变形。"}, {"other_code": "N_bdcbd964954e8535", "rule": "倾斜、裂缝与接缝监测侧重结构表面的局部破坏性变形；本节点侧重岩土体及支护结构的整体位移场与稳定性监测。"}], "cross_boundary_rule": "基坑或边坡监测数据若触发安全预警，可关联自动化监测与预警节点，但针对岩土工程对象的特定监测技术与方案主挂载本节点。"}, {"node_code": "N_0fee96d5af64422b", "definition": "利用自动化传感器、数据采集系统及信息处理技术，对工程变形进行实时或准实时监测、数据深度分析及安全预警的技术体系。", "boundary": "本节点聚焦于监测系统的“智能化”与“数据化”层面。涵盖自动化监测硬件集成、数据传输、多源数据融合分析、变形趋势预测及预警阈值设定。与具体变形类型（如沉降、倾斜）节点的区别在于，本节点不局限于特定物理量，而是强调监测手段的自动化与数据处理的通用性；与“工程安全检测”的区别在于，本节点侧重过程监测与预警，而非事后鉴定。", "includes": ["自动化监测传感器网络、数据采集与传输系统", "变形监测数据的清洗、融合、趋势分析及预测模型", "安全预警机制、阈值设定及可视化展示技术"], "excludes": ["具体的沉降、倾斜等单一物理量的传统人工测量方法（归入对应变形类型节点）", "基于监测结果的结构安全等级鉴定或承载力验算（归入工程安全、检测与运维）", "纯软件算法理论而不涉及工程监测应用的部分"], "sibling_distinctions": [{"other_code": "N_7557e10122fd3104", "rule": "沉降观测侧重垂直变形的测量技术与方法；本节点侧重利用自动化手段获取数据并进行综合分析与预警。"}, {"other_code": "N_bdcbd964954e8535", "rule": "倾斜、裂缝与接缝监测侧重局部变形的测量；本节点侧重监测系统的自动化集成及数据驱动的安全预警。"}], "cross_boundary_rule": "自动化监测技术若应用于特定对象（如基坑），可关联该对象监测节点，但通用的自动化系统架构、数据分析算法及预警模型主挂载本节点。"}]}
